import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0057: Foreground engine connection recovery","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0057-foreground-engine-connection-recovery.md","filePath":"adrs/0057-foreground-engine-connection-recovery.md","lastUpdated":1789092097000}`),u={name:`adrs/0057-foreground-engine-connection-recovery.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[3]||=a(`<h1 id="adr-0057-foreground-engine-connection-recovery" tabindex="-1">ADR-0057: Foreground engine connection recovery <a class="header-anchor" href="#adr-0057-foreground-engine-connection-recovery" aria-label="Permalink to “ADR-0057: Foreground engine connection recovery”">​</a></h1><p>Status: Accepted · 2026-09-07 · Refines ADRs 0023, 0025 and 0045.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>A failed startup probe could leave GOAT marked offline indefinitely after the configured engine became available. Recovery depended on an explicit health check or reopening engine settings. Transient engine startup and local-network availability should not require editing a correct profile.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The app owns one recovery controller, independent of individual chat and settings views. While GOAT is active and its active engine is offline, it retries after 1, 2, 4, 8, 16 and then 30 seconds between attempts. View updates join the existing loop. Healthy and authentication-required states do not start polling. An in-flight successful probe finishes publishing model capabilities before the loop retires.</p>`,6),c(`p`,null,[l[1]||=i(`Recovery uses the active profile's exact saved URL and credentials through the existing revisioned engine lifecycle. It does not discover fallback ports, rewrite profiles, generate completions or add network authority. Active turns, engine transitions and model capability checks prevent a recovery probe from starting. Inactive app state or a JUDAS-disallowed target cancels recovery. Every actual request remains independently governed by `,-1),r(m,{term:`judas`},{default:n(()=>[...l[0]||=[i(`JUDAS`,-1)]]),_:1}),l[2]||=i(`.`,-1)]),l[4]||=c(`p`,null,`An offline engine also exposes a direct Reconnect action beside its status. Edit/Test remains the configuration workflow.`,-1),l[5]||=c(`h2`,{id:`consequences-and-validation`,tabindex:`-1`},[i(`Consequences and validation `),c(`a`,{class:`header-anchor`,href:`#consequences-and-validation`,"aria-label":`Permalink to “Consequences and validation”`},`​`)],-1),l[6]||=c(`p`,null,`Healthy idle sessions have no recurring health timer. An offline foreground session makes bounded, backed-off requests to its configured service and can recover without a settings detour. Authentication errors still require user action. Returning to the app restarts recovery when needed; network recovery while it stays active can wait for the next retry interval.`,-1),l[7]||=c(`p`,null,`Deterministic tests cover single-flight scheduling, backoff, busy-turn suppression, cancellation and non-offline states. Existing engine-operation revisions prevent an older probe from publishing over a newer user action. No database migration, dependency or additional service configuration is introduced.`,-1)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};